# Regenerate supabase/functions/ask-rigroute/knowledge.ts from js/guide.js + data/changelog.json (run before deploying the function).
import json,re
src=open('js/guide.js').read(); items=re.findall(r"t: '((?:[^'\\]|\\.)*)', b: '((?:[^'\\]|\\.)*)'",src)
guide="\n".join(f"- {t.replace(chr(92)+chr(39),chr(39))}: {b.replace(chr(92)+chr(39),chr(39))}" for t,b in items)
log=json.load(open('data/changelog.json')); cl="\n".join(f"{e['date']} (v{e['version']}): "+" ".join(e['items']) for e in log)
open('supabase/functions/ask-rigroute/knowledge.ts','w').write("// GENERATED by scripts/ai-knowledge.py from js/guide.js + data/changelog.json. Do not edit.\nexport const GUIDE = "+json.dumps(guide)+";\nexport const CHANGELOG = "+json.dumps(cl)+";\n")
